// totp — RFC 6238 time-based one-time passwords (SHA256 variant)
// Digits: 6, period: 30s

const TOTP_DIGITS = 6;
const TOTP_PERIOD = 30;

fn totp_counter::(ts) { return @floor(ts / TOTP_PERIOD); }

fn counter_bytes::(counter) {
    let bytes = @array_fill(8, 0);
    let mut c = counter;
    for i in @range(0, 8) {
        bytes[7 - i] = @u8(c % 256);
        c = c / 256;
    }
    return @bytes(bytes);
}

fn totp_at::(secret, ts) {
    let counter = totp_counter(ts);
    let msg = counter_bytes(counter);
    let mac = @hmac_sha256(@base64_decode(secret), @bytes(msg));
    let offset = @mem_read_u16(@mem_from_bytes(mac), @len(mac) - 1) & 15;
    let code = ((mac[offset] & 127) * 16777216) +
               ((mac[offset + 1] & 255) * 65536) +
               ((mac[offset + 2] & 255) * 256) +
               (mac[offset + 3] & 255);
    let mod = 1;
    for i in @range(0, TOTP_DIGITS) { mod = mod * 10; }
    let digits = @str(code % mod);
    while (@len(digits) < TOTP_DIGITS) { digits = "0" + digits; }
    return digits;
}

fn totp_now::(secret) { return totp_at(secret, @time_ms() / 1000); }

fn totp_verify::(secret, token, window) {
    let now = @time_ms() / 1000;
    for w in @range(-window, window + 1) {
        if (totp_at(secret, now + w * TOTP_PERIOD) == token) { return true; }
    }
    return false;
}

fn totp_uri::(secret, label, issuer) {
    return "otpauth://totp/" + @url_encode(label) +
           "?secret=" + secret + "&issuer=" + @url_encode(issuer) +
           "&digits=" + @str(TOTP_DIGITS) + "&period=" + @str(TOTP_PERIOD);
}

fn version::() { return "1.0.0"; }
